def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n >= 5 and opp.count('D') > n * 0.5:
        return 'D'

    last_me = me[-1]
    last_opp = opp[-1]

    if last_me == 'D' and last_opp == 'C':
        return 'D'

    if last_me == 'D' and last_opp == 'D':
        return 'C'

    if last_me == 'C' and last_opp == 'D':
        if n >= 2 and me[-2] == 'C' and opp[-2] == 'D':
            return 'D'
        return 'C'

    if last_me == 'C' and last_opp == 'C':
        recent_opp = opp[-10:] if n >= 10 else opp
        if recent_opp.count('D') == 0:
            last_D = -1
            for i in range(n-1, -1, -1):
                if me[i] == 'D':
                    last_D = i
                    break
            if last_D == -1 or n - last_D > 10:
                return 'D'
        return 'C'

    return 'C'
